import {RETAIL_PLAYMATS} from './retail-playmats.js';
// Device-local appearance only. Card lists, game state and account payloads stay separate.
export const PLAYMAT_DB='duema.playmat.v1';
export const PLAYMAT_PRESETS=[['standard','標準'],['forest','深緑の紋章'],['ocean','蒼の波紋'],['ember','紅の炎紋'],...RETAIL_PLAYMATS.map(p=>[p.id,p.name])];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const searchKey=value=>String(value??'').normalize('NFKC').toLowerCase().trim();
const matchesSearch=(name,query)=>searchKey(query).split(/\s+/).filter(Boolean).every(word=>searchKey(name).includes(word));
const clamp=(v,min,max,fallback)=>Number.isFinite(Number(v))?Math.min(max,Math.max(min,Number(v))):fallback;
const imageOK=b=>b instanceof Blob&&['image/jpeg','image/png','image/webp'].includes(b.type)&&b.size>0&&b.size<=2*1024*1024;
export function normalizePlaymat(v){return {preset:[...PLAYMAT_PRESETS.map(p=>p[0]),'custom'].includes(v?.preset)?v.preset:'standard',brightness:clamp(v?.brightness??65,30,90,65),scale:clamp(v?.scale??100,100,180,100),x:clamp(v?.x??50,0,100,50),y:clamp(v?.y??50,0,100,50),image:imageOK(v?.image)?v.image:null};}
export function createPlaymatStore(idb=globalThis.indexedDB){
 async function open(){if(!idb)throw Error('このブラウザでは設定を保存できません。');return new Promise((resolve,reject)=>{const r=idb.open(PLAYMAT_DB,1);let blocked=false;r.onupgradeneeded=()=>r.result.createObjectStore('settings');r.onerror=()=>reject(Error('プレイマットの保存領域を開けませんでした。'));r.onblocked=()=>{blocked=true;reject(Error('別のタブを閉じて、もう一度お試しください。'));};r.onsuccess=()=>{if(blocked)r.result.close();else resolve(r.result);};});}
 async function transact(mode,value,key='current'){const db=await open();try{return await new Promise((resolve,reject)=>{const t=db.transaction('settings',mode),store=t.objectStore('settings'),r=mode==='readwrite'?store.put(value,key):store.get(key);let result;r.onsuccess=()=>{result=r.result;};t.oncomplete=()=>resolve(result);t.onabort=t.onerror=()=>reject(Error('設定を保存できませんでした。空き容量やブラウザの設定をご確認ください。'));});}finally{db.close();}}
 return {read:key=>transact('readonly',undefined,key),write:(v,key)=>transact('readwrite',v,key)};
}
// Decode and resize locally so a large phone photo never fills deck storage.
export async function preparePlaymatImage(file,{doc=globalThis.document,url=globalThis.URL,ImageClass=globalThis.Image}={}){
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('JPEG・PNG・WebPの画像を選んでください。');
 if(file.size>8*1024*1024)throw Error('画像は8MB以下にしてください。');
 const src=url.createObjectURL(file),img=new ImageClass();
 try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('画像を読み込めませんでした。別の画像をお試しください。'));img.src=src;});if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth*img.naturalHeight>32_000_000)throw Error('画像が大きすぎます。小さくしてから選び直してください。');const ratio=Math.min(1,2048/Math.max(img.naturalWidth,img.naturalHeight)),canvas=doc.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));const ctx=canvas.getContext('2d');if(!ctx)throw Error('画像を準備できませんでした。');ctx.fillStyle='#0b1718';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!imageOK(blob))throw Error('画像を保存サイズに収められませんでした。小さい画像を選んでください。');return blob;}finally{url.revokeObjectURL(src);}
}
export function createPlaymatController({doc=globalThis.document,store=createPlaymatStore(),url=globalThis.URL,prepareImage=preparePlaymatImage,onChange=()=>{}}={}){
 let state={...normalizePlaymat(),opponent:normalizePlaymat()},queue=Promise.resolve(),initialError='';
 // Separate deck keys let older clients keep saving current without erasing deck choices.
 const deckSettings=new Map(),deckLoads=new Map();let deckContext={own:null,opponent:null};
 const deckKey=id=>'deck:'+JSON.stringify(id),validId=id=>typeof id==='string'&&id.length?id:null;
 const configFor=(side,id=deckContext[side])=>normalizePlaymat(id&&deckSettings.get(id)|| (side==='opponent'?state.opponent:state));
 async function loadDeck(id){if(!id||deckSettings.has(id))return;if(deckLoads.has(id))return deckLoads.get(id);const job=Promise.resolve().then(()=>store.read(deckKey(id))).then(v=>{deckSettings.set(id,v?normalizePlaymat(v):null);}).finally(()=>deckLoads.delete(id));deckLoads.set(id,job);return job;}
 function setDecks(own=null,opponent=null){if(validId(own)===deckContext.own&&validId(opponent)===deckContext.opponent&&[own,opponent].every(id=>!validId(id)||deckSettings.has(id)))return Promise.resolve();deckContext={own:validId(own),opponent:validId(opponent)};apply();return Promise.all([loadDeck(deckContext.own),loadDeck(deckContext.opponent)]).then(()=>{apply();onChange();});}
 const imageURLs={own:{image:null,url:null},opponent:{image:null,url:null}};
 function apply(value=null,previewSide=null){const root=doc.documentElement,configs={own:snapshot(),opponent:snapshot('opponent')};
  if(value){if(previewSide)configs[previewSide]=normalizePlaymat(value);else{configs.own=normalizePlaymat(value);configs.opponent=normalizePlaymat(value.opponent??configs.opponent);}}
  for(const [side,p]of Object.entries(configs)){const cache=imageURLs[side],retail=RETAIL_PLAYMATS.find(r=>r.id===p.preset);if(cache.image!==p.image){if(cache.url)url.revokeObjectURL(cache.url);cache.url=p.image?url.createObjectURL(p.image):null;cache.image=p.image;}
   root.setAttribute(side==='own'?'data-playmat':'data-opponent-playmat',p.preset==='custom'&&!cache.url?'standard':p.preset);
   const values={'image':cache.url?'url("'+cache.url+'")':'none','retail-image':retail?'url("'+retail.local+'")':'none','shade':String(1-p.brightness/100),'scale':String(p.scale/100),'x':p.x+'%','y':p.y+'%'};
   for(const [key,value]of Object.entries(values)){root.style.setProperty('--'+side+'-playmat-'+key,value);if(side==='own')root.style.setProperty('--playmat-'+key,value);}
  }
 }
 apply();const ready=Promise.resolve().then(()=>store.read()).then(v=>{state={...normalizePlaymat(v),opponent:normalizePlaymat(v?.opponent??v)};apply();onChange();}).catch(e=>{initialError=e.message;});
 // Keep the original top-level fields for own settings; the other side is an optional additive record.
 function save(patch,side='own'){const deckId=deckContext[side];const job=queue.catch(()=>{}).then(async()=>{await ready;if(deckId)await loadDeck(deckId);const config=normalizePlaymat({...configFor(side,deckId),...patch});if(config.preset==='custom'&&!config.image)throw Error('先に画像を選んでください。');if(deckId){await store.write(config,deckKey(deckId));deckSettings.set(deckId,config);}else{const next=side==='opponent'?{...state,opponent:config}:{...config,opponent:state.opponent};await store.write(next);state=next;}apply();onChange();return {...config};});queue=job;return job;}
 function copyDeck(from,to){if(!validId(from)||!validId(to)||from===to)return Promise.resolve();const job=queue.catch(()=>{}).then(async()=>{await ready;await Promise.all([loadDeck(from),loadDeck(to)]);const value=deckSettings.get(from);if(!value||deckSettings.get(to))return;const config=normalizePlaymat(value);await store.write(config,deckKey(to));deckSettings.set(to,config);apply();onChange();});queue=job;return job;}
 function snapshot(side='own'){return {...configFor(side)};}
 function deckEntryHTML(name=''){const p=snapshot(),retail=RETAIL_PLAYMATS.find(r=>r.id===p.preset),label=p.preset==='custom'?'持ち込み画像':PLAYMAT_PRESETS.find(r=>r[0]===p.preset)?.[1]||'標準';return `<button type="button" class="deck-playmat-entry" data-action="deck-playmat-settings" data-deck-playmat-entry aria-label="このデッキのプレイマットを選ぶ"><span class="deck-playmat-thumb playmat-swatch" data-mat="${p.preset}" aria-hidden="true"${retail?' style="--playmat-pattern:var(--own-playmat-retail-image)"':p.preset==='custom'?' style="--playmat-pattern:var(--own-playmat-image)"':''}></span><span class="deck-playmat-copy"><strong>プレイマットを選ぶ</strong><span class="deck-playmat-name">${esc((deckContext.own&&!deckSettings.get(deckContext.own)?'共通設定：':'')+label)}</span><small>このデッキを使うと自動で切り替え</small></span><span class="deck-playmat-arrow" aria-hidden="true">›</span></button>`;}
 function html({deckName=null}={}){return `<div class="playmat-settings" data-playmat-settings ${deckName!==null?'data-playmat-single-deck':''}><p class="small">${deckName!==null?`「${esc(deckName||'名前のないデッキ')}」用のプレイマットです。このデッキを使う対戦で自動的に切り替えます。設定はこの端末だけに保存します。`:'自分の画面だけに適用します。画像と設定はこのブラウザに保存し、対戦相手には送りません。'}</p><div class="playmat-side-switch" ${deckName!==null?'hidden':''} role="group" aria-label="変更する側"><button type="button" data-playmat-side="own" aria-pressed="true">自分の場</button><button type="button" data-playmat-side="opponent" aria-pressed="false">相手の場 · 反対向き</button></div><div class="playmat-preview" data-playmat-preview="own" aria-label="プレイマットのプレビュー"><span>プレイマット</span><b aria-hidden="true">DUEL MASTERS</b><span data-playmat-preview-owner>自分側</span><i aria-hidden="true"></i></div><fieldset class="playmat-presets"><legend>プレイマットを選ぶ</legend>${PLAYMAT_PRESETS.filter(([id])=>!id.startsWith('retail-')).map(([id,label])=>`<button type="button" data-playmat-preset="${id}" aria-pressed="false"><span class="playmat-swatch" data-mat="${id}" aria-hidden="true"></span>${label}</button>`).join('')}<button type="button" data-playmat-preset="custom" aria-pressed="false"><span class="playmat-swatch" data-mat="custom" aria-hidden="true"></span>持ち込み画像</button></fieldset><label class="playmat-search">柄を名前で探す<input type="search" data-playmat-search placeholder="例：ドギラゴン、GP6th" autocomplete="off" aria-describedby="playmat-search-count"></label><p class="small" id="playmat-search-count" data-playmat-search-count aria-live="polite"></p><fieldset class="playmat-presets playmat-retail"><legend>商品・大会プレイマットの柄</legend>${RETAIL_PLAYMATS.map(r=>`<button type="button" data-playmat-retail-choice data-playmat-preset="${r.id}" aria-pressed="false"><img src="${r.local}" alt="" loading="lazy" decoding="async" width="1000" height="584"><span>${r.name}</span></button>`).join('')}</fieldset><p class="small" data-playmat-search-empty hidden>一致する柄がありません。別の名前で検索してください。</p><p class="playmat-product small" data-playmat-product hidden><strong data-playmat-product-name></strong><a data-playmat-product-link target="_blank" rel="noopener noreferrer">画像の掲載元・商品情報 ↗</a></p><label class="playmat-upload">画像を選ぶ<input type="file" accept="image/jpeg,image/png,image/webp" data-playmat-file><small>JPEG・PNG・WebP、8MBまで。${deckName!==null?'このデッキに1枚保存できます。':'自分側・相手側に各1枚保存できます。'}</small></label><div class="playmat-adjustments">${[['brightness','画像の明るさ',30,90,'%'],['scale','拡大率',100,180,'%'],['x','左右の位置',0,100,'%'],['y','上下の位置',0,100,'%']].map(([key,label,min,max,unit])=>`<label>${label}<output data-playmat-output="${key}"></output><input type="range" min="${min}" max="${max}" step="1" data-playmat-control="${key}" aria-label="${label}" data-unit="${unit}"></label>`).join('')}</div><div class="playmat-tools"><button type="button" class="btn" data-playmat-reset>位置・明るさを戻す</button><button type="button" class="btn" data-playmat-remove>保存した画像を削除</button></div><p class="notice" role="status" aria-live="polite" data-playmat-status>設定を読み込み中…</p></div>`;}
 async function mount(container){await ready;if(!container?.isConnected)return;let busy=false,side='own';const singleDeck=container.hasAttribute?.('data-playmat-single-deck');
  const status=text=>{container.querySelector('[data-playmat-status]').textContent=text;};
  function filter(){const query=container.querySelector('[data-playmat-search]')?.value??'';let count=0;for(const el of container.querySelectorAll('[data-playmat-retail-choice]')){const r=RETAIL_PLAYMATS.find(r=>r.id===el.dataset.playmatPreset);el.hidden=!matchesSearch(r?.name??'',query);if(!el.hidden)count++;}container.querySelector('[data-playmat-search-count]').textContent=count+' / '+RETAIL_PLAYMATS.length+'柄';container.querySelector('[data-playmat-search-empty]').hidden=count>0;}
  function sync(){const p=snapshot(side);container.style?.setProperty('--playmat-image','var(--'+side+'-playmat-image)');for(const el of container.querySelectorAll('[data-playmat-side]')){el.setAttribute('aria-pressed',String(el.dataset.playmatSide===side));el.disabled=busy;}container.querySelector('[data-playmat-preview]')?.setAttribute?.('data-playmat-preview',side);container.querySelector('[data-playmat-preview-owner]').textContent=singleDeck?'このデッキ':side==='own'?'自分側':'相手側 · 180度回転';const retail=RETAIL_PLAYMATS.find(r=>r.id===p.preset),product=container.querySelector('[data-playmat-product]');product.hidden=!retail;if(retail){container.querySelector('[data-playmat-product-name]').textContent=(singleDeck?'選択中：':side==='own'?'自分側：':'相手側：')+retail.name;container.querySelector('[data-playmat-product-link]').href=retail.source;}for(const el of container.querySelectorAll('[data-playmat-preset]')){el.setAttribute('aria-pressed',String(el.dataset.playmatPreset===p.preset));el.disabled=busy||el.dataset.playmatPreset==='custom'&&!p.image;}for(const el of container.querySelectorAll('[data-playmat-control]')){el.value=p[el.dataset.playmatControl];el.disabled=busy||p.preset==='standard'||['scale','x','y'].includes(el.dataset.playmatControl)&&p.preset!=='custom'&&!p.preset.startsWith('retail-');container.querySelector(`[data-playmat-output="${el.dataset.playmatControl}"]`).textContent=el.value+'%';}container.querySelector('[data-playmat-file]').disabled=busy;container.querySelector('[data-playmat-remove]').disabled=busy||!p.image;container.querySelector('[data-playmat-reset]').disabled=busy;filter();}
  async function commit(fn){busy=true;sync();status('保存しています…');try{await fn();status('このブラウザに保存しました。');}catch(e){apply();status(e.message||'設定を保存できませんでした。');}finally{busy=false;if(container.isConnected)sync();}}
  sync();status(initialError||'変更は自動で保存されます。');
  container.addEventListener('click',event=>{if(busy)return;const el=event.target.closest('button');if(!el)return;if(el.dataset.playmatSide){side=el.dataset.playmatSide;sync();status('選んだ側の設定を変更します。');return;}if(el.dataset.playmatPreset)commit(()=>save({preset:el.dataset.playmatPreset},side));else if(el.hasAttribute('data-playmat-reset'))commit(()=>save({brightness:65,scale:100,x:50,y:50},side));else if(el.hasAttribute('data-playmat-remove'))commit(()=>save({image:null,...(snapshot(side).preset==='custom'?{preset:'standard'}:{})},side));});
  container.addEventListener('input',event=>{const el=event.target;if(el.hasAttribute?.('data-playmat-search')){filter();return;}const key=el.dataset.playmatControl;if(busy||!key)return;apply({...snapshot(side),[key]:Number(el.value)},side);container.querySelector(`[data-playmat-output="${key}"]`).textContent=el.value+'%';});
  container.addEventListener('change',event=>{if(busy)return;const el=event.target,key=el.dataset.playmatControl;if(key){const value=Number(el.value);commit(()=>save({[key]:value},side));}if(el.hasAttribute('data-playmat-file')){const file=el.files?.[0];el.value='';if(file)commit(async()=>{const image=await prepareImage(file);await save({image,preset:'custom',scale:100,x:50,y:50},side);});}});
 }
 return {ready,snapshot,save,apply,html,mount,setDecks,deckEntryHTML,copyDeck};
}
